-- Dansk portion 8 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3344-6574.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish8'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish8', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3344,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad kaldes et talord som 'syvende' i sætningen: 'Hun sidder på syvende række.'","o":["grundtal","udråbsord","stedord","ordenstal"],"a":"ordenstal","r":"'Syvende' fortæller, hvilken plads rækken har i en rækkefølge. Derfor hedder det et ordenstal."},
{"l":3366,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find ordet, der passer: 'Efter festen var alle skålene ___.'","o":["tomme","tommer","toume","tome"],"a":"tomme","r":"Grundformen er 'tom'. I flertal fordobles m'et, fordi o'et er kort."},
{"l":3388,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Hun har ___ mig sit nye værelse.'","o":["vidst","vist","visst","hvist"],"a":"vist","r":"Ordet kommer af 'at vise', og det er der ikke noget d i. Med d ville det betyde noget med at vide."},
{"l":3406,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen er en stjerne. Den ser større ud end andre stjerner, fordi den er så tæt på os. Mange af de små prikker, du kan se på himlen om natten, er faktisk meget større end solen. De er bare så langt væk, at de ser små ud.' Hvad vil teksten lære læseren?","o":["At solen er den største stjerne i rummet","At stjernerne på himlen kun kan ses om natten","At afstand påvirker, hvor stor en stjerne ser ud","At alle stjerner er lige store, når man måler dem"],"a":"At afstand påvirker, hvor stor en stjerne ser ud","r":"Teksten forklarer, at noget ser stort ud på grund af afstanden. Det er forklaringen, ikke stjernernes rigtige størrelse."},
{"l":3430,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"En 'årvågen' nabo så røgen fra loftet. Hvordan er sådan en nabo?","o":["Naboen sover tit langt ud på formiddagen","Naboen er meget nysgerrig efter andres penge","Naboen er ofte sur og klager over larmen","Naboen er opmærksom og lægger mærke til ting"],"a":"Naboen er opmærksom og lægger mærke til ting","r":"Årvågen betyder vagtsom og opmærksom. Man holder øje med, hvad der sker omkring en."},
{"l":3445,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad viser du, når du trøster en klassekammerat, der er ked af det?","o":["medfølelse","misundelse","overmod","nysgerrighed"],"a":"medfølelse","r":"Medfølelse betyder, at man føler med et andet menneske og gerne vil hjælpe."},
{"l":3467,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en elev, der er 'vedholdende'?","o":["Eleven giver hurtigt op, når det driller","Eleven bliver ved, selvom det er svært","Eleven holder altid døren for de andre","Eleven kommer ofte for sent til timen"],"a":"Eleven bliver ved, selvom det er svært","r":"Vedholdende betyder, at man holder ved og ikke giver op, selvom noget tager lang tid."},
{"l":3487,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er den lange tillægsform af 'at smile', som i 'et ___ ansigt'?","o":["smilet","smilede","smilende","smiler"],"a":"smilende","r":"Den lange tillægsform ender på -ende og kan bruges som et tillægsord."},
{"l":3505,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Hans red på sin gedebuk og havde en død krage, en gammel træsko og lommerne fulde af mudder med til prinsessen.' Hvilket af H.C. Andersens eventyr er det?","o":["Fyrtøjet","Tommelise","Svinedrengen","Klods-Hans"],"a":"Klods-Hans","r":"Klods-Hans samler ting op på vejen, og hans brødre griner af ham. Men tingene giver ham de bedste svar, da han møder prinsessen."},
{"l":3527,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad skal stå på stregen: 'I middelalderen ejede ___ store godser og havde særlige rettigheder.'","o":["adelen","fæstebønderne","trællene","lærlingene"],"a":"adelen","r":"Adelen var det fornemme lag i samfundet. Fæstebønder ejede ikke selv deres jord, men lejede den."},
{"l":3542,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Egernet gemmer ___ til vinteren.'","o":["nøder","nødder","nødre","nødere"],"a":"nødder","r":"Ental er 'nød'. D'et fordobles i flertal, fordi ø'et bliver kort."},
{"l":3565,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad sker der under 'fordøjelsen'?","o":["Luften bliver renset i lungerne, før den når blodet","Blodet bliver pumpet rundt i kroppen af hjertet","Maden bliver nedbrudt, så kroppen kan optage næringen","Musklerne bliver stærkere, når man dyrker motion"],"a":"Maden bliver nedbrudt, så kroppen kan optage næringen","r":"I mave og tarme bliver maden brudt ned til små dele, så næringen kan komme over i blodet."},
{"l":3586,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form er rigtig? 'Jeg slog to ___ på bordbenet.'","o":["tåer","tær","tæder","tæer"],"a":"tæer","r":"Ental er 'tå'. I flertal skifter å til æ, og ordet ender på -er."},
{"l":3603,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sofus og hans søster deltes om et værelse. Han tegnede en streg på gulvet med kridt og sagde: Her går grænsen. Hun gik over stregen for at komme ud ad døren. Om aftenen, da det blev tordenvejr, kom hun ind på hans side med sin dyne. Han sagde ikke noget, men flyttede sig.' Hvad er ændret i slutningen?","o":["Sofus giver slip på stregen af omsorg for søsteren","Søsteren har fået sit eget værelse af forældrene","Sofus har sat en ny kridtstreg op ved døren","Søsteren har vundet et stort skænderi mod Sofus"],"a":"Sofus giver slip på stregen af omsorg for søsteren","r":"Han flytter sig uden at sige noget. Hans grænse betyder mindre, når søsteren er bange."},
{"l":3621,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Gamle Jens på gården havde en hest, der var for gammel til at arbejde. Naboen sagde, at den var en udgift. Jens svarede ikke, men hver aften gik han ud i stalden med et æble. Han havde ingen andre at tale med, og hesten havde altid lyttet.' Hvorfor beholder Jens hesten?","o":["Han vil sælge den for flere penge senere","Den er hans selskab, og han holder af den","Han håber, at den igen kan arbejde på gården","Han vil vise naboen, at han har mange penge"],"a":"Den er hans selskab, og han holder af den","r":"Hesten er ikke til gavn i arbejdet, men Jens har ingen andre at tale med. Det er følelser, ikke penge, der styrer ham."},
{"l":3641,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'På lejrskolen sov vi tre ___ i telt.'","o":["nater","næter","nætter","nattere"],"a":"nætter","r":"Ental er 'nat'. I flertal skifter a til æ, og t'et fordobles."},
{"l":3663,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er det rigtige ord? 'De sidste to ___ var vi på ferie i Sverige.'","o":["sommere","sommer","sommre","somre"],"a":"somre","r":"I flertal falder e'et væk, og så står der kun ét m foran r."},
{"l":3684,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sådan laver du en vulkan: Stil en lille flaske i en bakke. Hæld bagepulver, sæbe og lidt rød farve i flasken. Når du er klar, hælder du eddike i. Skummet stiger op og løber ned ad siderne. Husk at gøre det udenfor eller i en stor balje.' Hvorfor skal du nok bruge en bakke eller balje?","o":["Fordi skummet ellers kan sprede sig","Fordi vulkanen ellers ikke kan gå i gang","Fordi flasken ellers bliver for varm","Fordi eddiken ellers ikke vil blive rød"],"a":"Fordi skummet ellers kan sprede sig","r":"Skummet løber ned ad siderne. Man kan slutte, at bakken skal samle det op, så det ikke sviner."},
{"l":3700,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lars havde fået en ny cykel. Han lod den stå midt på skolegården, hvor alle kunne se den, også da det begyndte at regne.' Hvad er Lars især optaget af?","o":["At holde cyklen tør og ren","At blive set med cyklen","At komme hurtigt hjem","At få solgt den gamle cykel"],"a":"At blive set med cyklen","r":"Han lader den stå fremme, selv i regn. Det viser, at det vigtige er, hvad andre ser, ikke selve cyklen."},
{"l":3720,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Nu går det op, op, op, / helt op til bjergets top.' Hvilket virkemiddel er der i første linje?","o":["sammenligning","overdrivelse","gentagelse","lydord"],"a":"gentagelse","r":"Ordet 'op' står flere gange lige efter hinanden. Gentagelsen giver rytme, og man mærker, hvordan turen bliver ved."},
{"l":3740,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led er 'til Noa' i sætningen: 'Morfar gav en hammer til Noa.'","o":["genstandsled","grundled","udsagnsled","forholdsordsled"],"a":"forholdsordsled","r":"Leddet begynder med forholdsordet 'til'. Derfor er det et forholdsordsled."},
{"l":3762,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find ordet: 'Jeg ___ min jakke på skolen i går.'","o":["glemte","glemmede","glemmte","glæmte"],"a":"glemte","r":"Datid ender på -te, og foran t står der kun ét m, selvom nutid har to."},
{"l":3782,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad forstår man ved ordet 'klima'?","o":["vejret i et område på en bestemt dag","det typiske vejr i et område over mange år","hvor hurtigt skyerne flytter sig over landet","hvor mange mennesker der bor i et område"],"a":"det typiske vejr i et område over mange år","r":"Vejret er det, du ser ud ad vinduet i dag. Klima er gennemsnittet over mange år."},
{"l":3799,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Dyrlægen tog sit stetoskop af og så på Johan. Hunden lå stille på bordet og slikkede hans hånd. – Den er gammel, sagde dyrlægen blidt, og den har haft et godt liv. Far lagde en arm om Johans skuldre. Johan nikkede, men han sagde ingenting.' Hvad forstår læseren?","o":["At hunden snart bliver helt rask igen","At Johan er vred på sin far","At hunden nok snart skal dø","At dyrlægen ikke kender hunden godt"],"a":"At hunden nok snart skal dø","r":"Dyrlægens blide ord og fars arm viser, at der er tale om et farvel, selvom ingen siger det direkte."},
{"l":3820,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes den store ændring af kirken i 1500-tallet, som i Danmark blev gennemført i 1536?","o":["renæssancen","enevælden","oplysningstiden","reformationen"],"a":"reformationen","r":"Reformere betyder at omdanne. I 1536 gik den danske kirke fra at være katolsk til at være luthersk."},
{"l":3839,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Hvem har ___ min blyant?'","o":["taget","tajet","tagt","tæget"],"a":"taget","r":"Efter 'har' ender ordet på -et. G'et skal skrives, selvom det næsten ikke høres."},
{"l":3861,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Hun har allerede ___ tre sider i sin stil.'","o":["skrevvet","skrevet","skrivet","skreve"],"a":"skrevet","r":"I kort tillægsform skifter i til e, og ordet ender på -et med kun ét v."},
{"l":3880,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Pandaer spiser næsten kun bambus. Bambus indeholder ikke ret meget næring, så pandaen må spise i over ti timer om dagen. Den bruger sin tid på at spise og hvile for at spare på kræfterne. Derfor bevæger den sig langsomt.' Hvad er grunden til, at pandaen er langsom?","o":["Den har for korte ben til at løbe","Den er bange for at falde i bambus","Dens mad giver den ikke meget energi","Den er meget stor og har ingen fjender"],"a":"Dens mad giver den ikke meget energi","r":"Kæden i teksten er: lidt næring i maden, derfor spare på kræfterne, derfor langsom."},
{"l":3900,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'I starten var Mikkel bange for at tale i klassen. Til sidst stod han frem og læste sin historie højt.' Hvad er der sket med hovedpersonen?","o":["Han har ikke ændret sig i løbet af historien","Han er blevet mere bange for at tale højt","Han har skiftet skole og fået nye venner","Han har udviklet sig og er blevet modigere"],"a":"Han har udviklet sig og er blevet modigere","r":"Ved at sammenligne starten med slutningen kan man se, om en person har ændret sig. Mikkel tør noget nu, som han ikke turde før."},
{"l":3916,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at stege': 'Den ___ kylling smagte godt.'","o":["stegte","stegt","steger","stege"],"a":"stegte","r":"Når tillægsformen står efter 'den' foran et navneord, skal den have bestemt form, ligesom et tillægsord."},
{"l":3938,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at løbe': 'Hunden kom ___ hen over plænen.'","o":["løbet","løbende","løb","løber"],"a":"løbende","r":"Efter 'kom' siger man, hvordan nogen kommer, med den lange tillægsform på -ende."},
{"l":3960,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Anna hjælper Bo, og Bo hjælper Anna. Hvilket ord passer: 'Anna og Bo hjælper ___.'","o":["dem","sig","hinanden","deres"],"a":"hinanden","r":"Når to gør det samme mod hinanden, bruger man det gensidige stedord 'hinanden'."},
{"l":3979,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da solen var gået ned, sagde de to piger farvel ved broen. De havde været veninder i syv år. I morgen skulle Sofia flytte til Aalborg. – Vi ses, sagde Mira og prøvede at lyde, som om det var en helt almindelig dag. Så gik hun hjem uden at vende sig om, for hun ville ikke have, at Sofia skulle se hendes ansigt.' Hvorfor vender Mira sig ikke om?","o":["Hun er vred på Sofia, fordi hun flytter","Hun skal skynde sig hjem, før det bliver mørkt","Hun er ligeglad med, at Sofia flytter","Hun vil skjule, at hun er ked af det"],"a":"Hun vil skjule, at hun er ked af det","r":"Hun prøver at virke almindelig, og hendes ansigt ville afsløre, hvad hun føler. Det er det, hun skjuler."},
{"l":4004,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form passer? 'Far ___ altid bilen bag huset.'","o":["parkerer","parkere","parkeret","parkerrer"],"a":"parkerer","r":"Navnemåden ender på -ere, og nutid får et r mere, så ordet slutter på -erer."},
{"l":4022,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler: 'Det er en ___ at tro, at alle fra den samme by er ens.'","o":["fornøjelse","fordom","fortjeneste","forklaring"],"a":"fordom","r":"For- betyder før, og dom er en vurdering. Den med fordomme dømmer andre på forhånd uden at kende dem."},
{"l":4041,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bronze er en blanding af kobber og tin. Da mennesker opdagede bronzen for flere tusind år siden, kunne de lave stærkere våben og redskaber end af sten. Men tin fandtes ikke i Danmark, og kobber heller ikke. Derfor måtte folk her handle med fjerne lande.' Hvilken virkning havde bronzen på folk i Danmark?","o":["De holdt op med at bruge redskaber helt","De kunne finde tin i deres egne moser","De fik kontakt til folk i andre lande","De begyndte at sælge kobber til andre"],"a":"De fik kontakt til folk i andre lande","r":"Fordi metallerne ikke fandtes her, måtte man handle med fjerne lande. Handel skaber kontakt."},
{"l":4059,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Dagbog, tirsdag: I dag sagde Mette, at hun ikke længere ville være min bedste veninde. Alle kunne høre det. Jeg sagde, at det var fint med mig. Bagefter gik jeg ud på toilettet og blev der resten af frikvarteret. Jeg har ikke fortalt det til mor.' Hvad kan man slutte ud af skribentens ord?","o":["Hun er glad for at slippe af med Mette","Hun har fået ondt i maven af skolemaden","Hun har fundet en ny bedste veninde","Hun skjuler, hvor ondt det gør på hende"],"a":"Hun skjuler, hvor ondt det gør på hende","r":"Hun siger, at det er fint, men gemmer sig på toilettet og fortæller det ikke hjemme. Handlingerne afslører følelsen."},
{"l":4081,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En varm dag i april kan man kalde en ___. Hvad er stavet rigtigt?","o":["forårsdag","forårdag","foråresdag","forresdag"],"a":"forårsdag","r":"Ordet er sammensat med et fuge-s efter 'forår'. Det binder de to dele sammen."},
{"l":4100,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Kommer du for sent må du vente til næste hold.'?","o":["du","sent","må","vente"],"a":"sent","r":"'Kommer du for sent' betyder 'hvis du kommer for sent'. Det er en ledsætning uden bindeord, og den slutter med 'sent'."},
{"l":4119,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Ella tænkte___ »Det her klarer jeg.«'?","o":["punktum","udråbstegn","kolon","spørgsmålstegn"],"a":"kolon","r":"Tanker kan skrives som direkte tale. Så står der kolon efter 'tænkte', ligesom efter 'sagde'."},
{"l":4138,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken del af sætningen er ledsætningen: 'Hvad der skete i går, ved ingen.'?","o":["ved ingen","der skete","i går, ved ingen","Hvad der skete i går"],"a":"Hvad der skete i går","r":"Ledsætningen går fra 'Hvad' hen til kommaet. Den er grundled i hovedsætningen 'ved ingen'."},
{"l":4158,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Jeg har fået en ___ til Noahs fødselsdag.'","o":["invitation","invetation","imvitation","invitasjon"],"a":"invitation","r":"Ordet kommer af 'invitere' og ender på -tion. Der er v efter n og i efter v."},
{"l":4180,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Vi købte bukserne i en lille ___ på hjørnet.'","o":["buttik","butik","butikk","bodik"],"a":"butik","r":"Ordet er et lånord med ét t og ét k til sidst. Endelsen -ik har ikke dobbelt k."},
{"l":4195,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Det var Onsdag, da Nora fra Grenaa fandt et stykke rav på Anholt.'?","o":["Nora","Grenaa","Onsdag","Anholt"],"a":"Onsdag","r":"Ugedage skrives med lille inde i en sætning. Nora, Grenaa og Anholt er navne på en person, en by og en ø."},
{"l":4214,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvordan vi skal løse opgaven finder vi ud af i morgen.'?","o":["løse","finder","ud","opgaven"],"a":"opgaven","r":"'Hvordan vi skal løse opgaven' er en ledsætning, der står først. Hovedsætningen begynder med 'finder'."},
{"l":4235,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find bindeordet: 'Dunja spurgte, om vi ville med.'","o":["om","spurgte","vi","ville"],"a":"om","r":"'Om' indleder her en ledsætning, så det er et bindeord. I 'en bog om heste' ville det være et forholdsord."},
{"l":4257,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet i spørgsmålet: 'Har du fodret kaninerne?'","o":["Har","du","fodret","kaninerne"],"a":"du","r":"I et spørgsmål kan udsagnsleddet stå først. Spørg: Hvem har fodret? Det er 'du'."},
{"l":4277,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det, nogen gør, når de 'sætter sig på den høje hest'?","o":["Tør noget, som andre ikke har turdet før","Bliver gode til at ride på store heste","Opfører sig, som om de er bedre end andre","Sætter sig højt op, så de kan få overblik"],"a":"Opfører sig, som om de er bedre end andre","r":"På den høje hest ser man ned på andre. Vendingen bruges om dem, der virker overlegne og belærende."},
{"l":4298,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Min søster er en meget ___ elev, der altid laver sine lektier.'","o":["flitig","flidig","flitti","flittig"],"a":"flittig","r":"Dobbelt t, fordi i'et er kort. Endelsen -ig har et stumt g."},
{"l":4318,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilket år blev H.C. Andersen født?","o":["i 1805","i 1705","i 1855","i 1905"],"a":"i 1805","r":"H.C. Andersen blev født i Odense i 1805 og døde i 1875. Han levede altså i 1800-tallet."},
{"l":4340,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket af disse ord er et navneord dannet af tillægsordet 'fri'?","o":["frigive","frihed","fritage","frit"],"a":"frihed","r":"Endelsen -hed laver navneord af tillægsord, ligesom i 'tryghed'. 'Frigive' og 'fritage' er udsagnsord."},
{"l":4358,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Dyret har et hårdt skjold på ryggen og bevæger sig langsomt. Hvordan staves det?","o":["skilpadde","skilddpadde","skildpadde","skildepadde"],"a":"skildpadde","r":"Ordet indeholder 'skjold' i en gammel form, så d'et efter l skal med, selvom det er stumt."},
{"l":4378,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Viggo kan virke sur, men han 'har hjertet på rette sted'. Hvad betyder det?","o":["han har det fint efter sit besøg hos lægen","han ved altid, hvor han skal gå hen","han bliver hurtigt forelsket i nogen","han er et godt og omsorgsfuldt menneske"],"a":"han er et godt og omsorgsfuldt menneske","r":"Udtrykket bruges om en person, der vil andre det godt, også selv om det ikke altid ses udenpå."},
{"l":4399,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"'Hun' er et stedord i sætningen 'Hun sover længe.' Hvad hedder ordklassen på latin?","o":["pronomen","substantiv","adverbium","verbum"],"a":"pronomen","r":"Pronomen er det latinske ord for stedord. Det står i stedet for et navn eller et navneord."},
{"l":4415,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det ord, der passer: 'Efter regnskyllet var gaderne ___, og bilerne måtte vende om.'","o":["overvældede","oversvømmede","oversatte","overdrevne"],"a":"oversvømmede","r":"Når vand dækker en gade, er den oversvømmet. Ordene ligner hinanden, men kun dette handler om vand."},
{"l":4438,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er forskellen på en fabel og et eventyr?","o":["En fabel skal handle om prinser og prinsesser","En fabel skal være skrevet på rim og vers","En fabel er kort og har en tydelig moral","En fabel skal foregå på et kongeslot"],"a":"En fabel er kort og har en tydelig moral","r":"En fabel er kort og vil lære læseren noget bestemt. Et eventyr er længere og har mere handling og trylleri."},
{"l":4454,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvor skal 'aldrig' stå i ledsætningen om bogen?","o":["Det er en bog, som jeg har aldrig læst.","Det er en bog, som aldrig jeg har læst.","Det er en bog, som jeg har læst aldrig.","Det er en bog, som jeg aldrig har læst."],"a":"Det er en bog, som jeg aldrig har læst.","r":"I en ledsætning står biord som 'aldrig' og 'ikke' foran udsagnsordet. Det er modsat hovedsætningen."},
{"l":4476,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hele grundleddet: 'Manden med hatten smilede til mig.'","o":["Manden med hatten","med hatten","smilede","til mig"],"a":"Manden med hatten","r":"'Med hatten' fortæller, hvilken mand det er, og hører derfor med til grundleddet."},
{"l":4498,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mener man med at 'have en finger med i spillet'?","o":["at snyde, når man spiller kort med andre","at være med til at påvirke det, der sker","at have slået sig under en håndboldkamp","at se på, mens andre spiller et spil"],"a":"at være med til at påvirke det, der sker","r":"Man bruger udtrykket om en, der har indflydelse på en sag, ofte uden at det er tydeligt for alle."},
{"l":4513,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man en person, der hver dag rejser langt mellem sit hjem og sit arbejde?","o":["nomade","turist","pendler","eneboer"],"a":"pendler","r":"En pendler bevæger sig frem og tilbage som et pendul. En nomade flytter derimod hele sin bolig fra sted til sted."},
{"l":4534,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Hvad er det, der går og går, men aldrig kommer hen til døren?' Hvilken lille genre er det?","o":["fabel","ordsprog","brev","gåde"],"a":"gåde","r":"En gåde er et spørgsmål, man skal gætte svaret på. Svaret her er et ur."},
{"l":4553,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at smøre': 'Lasse har ___ sin egen madpakke.'","o":["smurt","smurte","smører","smøre"],"a":"smurt","r":"Efter 'har' står tillægsformen 'smurt'. 'Smurte' er datid."},
{"l":4575,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort i: 'Vi bor tæt på limfjorden, og vores hus er gult.'?","o":["hus","limfjorden","gult","vores"],"a":"limfjorden","r":"Limfjorden er navnet på et bestemt farvand, og geografiske navne skrives med stort."},
{"l":4595,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Opladeren skal sidde i stikkontakten, før du tilslutter cyklens batteri. Lyser lampen rødt, er batteriet ved at lade op. Lyser den grønt, er det fuldt opladet. Blinker den rødt, må du tage stikket ud og kontakte forhandleren. Oplad ikke batteriet i direkte sol.' Hvad skal du gøre, hvis lampen blinker rødt?","o":["Vente til lampen lyser grønt","Sætte batteriet ud i skyggen","Afbryde og ringe til forhandleren","Tage batteriet ud og oplade igen"],"a":"Afbryde og ringe til forhandleren","r":"Brugsanvisningen siger, at man skal tage stikket ud og kontakte forhandleren, når lampen blinker rødt."},
{"l":4608,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er 'at' i sætningen: 'Det er sjovt at bage.'","o":["bindeord","forholdsord","stedord","navneformsmærke"],"a":"navneformsmærke","r":"Her står 'at' foran udsagnsordet 'bage' i navneform. Så kaldes det navneformsmærke."},
{"l":4628,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad viser streger bag en løbende figur i en tegneserie?","o":["At figuren bevæger sig hurtigt","At figuren fryser i kulden","At figuren er meget træt","At figuren er blevet usynlig"],"a":"At figuren bevæger sig hurtigt","r":"Billeder står stille, men fartstreger giver indtryk af bevægelse. Sådan viser tegneren fart uden ord."},
{"l":4649,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord bruger man om en person med meget stor viden om et bestemt emne?","o":["amatør","ekspert","nybegynder","tilskuer"],"a":"ekspert","r":"En ekspert er særligt kyndig på et område. En amatør dyrker noget i fritiden og har ikke det som fag."},
{"l":4670,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den bedste præstation nogensinde i en disciplin: Hvordan staves det?","o":["verdenrekord","verdesrekord","verdensrekord","værdensrekord"],"a":"verdensrekord","r":"Ordet har fuge-s efter 'verden'. 'Verden' staves med e, selvom det kan lyde som æ."},
{"l":4687,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Skolen tager 'chikane' alvorligt. Hvad er det?","o":["at nogen ved et uheld kommer til at støde ind i en","at nogen roser en foran hele klassen","at nogen låner noget uden at spørge først","at nogen bliver ved med at genere en med vilje"],"a":"at nogen bliver ved med at genere en med vilje","r":"Chikane er bevidst og gentagen plage, der skal gøre livet ubehageligt for en anden."},
{"l":4702,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord bruger man om en håndskrift, der er så tydelig, at man kan tyde den?","o":["læselig","læsning","oplæst","læserinde"],"a":"læselig","r":"Endelsen -lig viser her, at noget kan lade sig gøre. En læselig tekst er altså til at læse."},
{"l":4724,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en forening havde 'underskud' sidste år?","o":["at den fik flere penge ind, end den brugte","at den brugte flere penge, end den fik ind","at den manglede frivillige til arbejdet","at den havde for mange nye medlemmer"],"a":"at den brugte flere penge, end den fik ind","r":"Underskud betyder, at der mangler penge i regnskabet. Det modsatte kaldes overskud."},
{"l":4742,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Det var en ___ idé at tage regntøj med.'","o":["glimmrende","glimerende","glimrende","glimrene"],"a":"glimrende","r":"Ordet har ét m lige foran r, og det ender på -ende."},
{"l":4762,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en video 'går viralt'?","o":["at den indeholder en farlig computervirus","at den bliver slettet af den, der lagde den op","at den kun kan ses af ens nærmeste venner","at den bliver delt af rigtig mange på kort tid"],"a":"at den bliver delt af rigtig mange på kort tid","r":"Udtrykket bruger billedet af en virus: Videoen spreder sig fra person til person, men den er ikke farlig."},
{"l":4784,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hensynsleddet: 'Jeg skylder Mohamed ti kroner.'","o":["Mohamed","ti kroner","Jeg","skylder"],"a":"Mohamed","r":"Pengene skal gå til Mohamed, så han er hensynsled. 'Ti kroner' er genstandsled."},
{"l":4800,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tak til busselskabet for den spændende morgenoplevelse. Det er altid hyggeligt at stå 40 minutter i regnen og gætte, om bussen kommer i dag.' Hvilken tone har indlægget?","o":["Taknemmelig og glad","Ironisk og irriteret","Bekymret og trist","Neutral og saglig"],"a":"Ironisk og irriteret","r":"Ordene 'tak' og 'hyggeligt' passer ikke til situationen. Skribenten siger det modsatte af, hvad der menes, og det kaldes ironi."},
{"l":4817,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at skrælle': 'De ___ æbler lå i skålen.'","o":["skrællet","skræller","skrællede","skrælle"],"a":"skrællede","r":"Foran et navneord i flertal får tillægsformen -e, ligesom et tillægsord. Den bliver derfor til 'skrællede'."},
{"l":4838,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find ordet: 'Du kan finde mere ___ på skolens hjemmeside.'","o":["imformation","informasjon","informasion","information"],"a":"information","r":"Der står n foran f, selvom det kan lyde som m. Endelsen er -tion."},
{"l":4860,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Find pladsen til kommaet: 'Mens vi ventede på bussen begyndte det at sne.'","o":["efter bussen","efter ventede","efter begyndte","efter det"],"a":"efter bussen","r":"Ledsætningen 'Mens vi ventede på bussen' slutter efter 'bussen'. Derefter kommer hovedsætningen."},
{"l":4875,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Det danske hold måtte 'bide i græsset' i semifinalen. Hvad skete der?","o":["holdet vandt","holdet tabte","holdet kom for sent","holdet holdt pause"],"a":"holdet tabte","r":"At bide i græsset betyder at tabe eller lide nederlag. Det har ikke noget med mad at gøre."},
{"l":4897,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'slog' i sætningen 'Det slog mig, at hun var blevet så stille'?","o":["det ramte mig hårdt på kroppen","det besejrede mig i en kamp","det gik pludselig op for mig","det gjorde mig meget vred"],"a":"det gik pludselig op for mig","r":"Her er 'slå' brugt i overført betydning: En tanke dukker pludselig op. Ingen bliver ramt fysisk."},
{"l":4913,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Jeg havde kun ti sekunder til at finde nøglen.' Teksten begynder lige midt i handlingen. Hvad er virkningen?","o":["Læseren bliver hurtigt træt af teksten","Læseren får hele slutningen at vide","Læseren får personernes baggrund først","Læseren får straks lyst til at læse videre"],"a":"Læseren får straks lyst til at læse videre","r":"Når en tekst starter midt i noget spændende, vil man vide, hvad der sker. Baggrunden kan så komme senere."},
{"l":4935,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer bedst til en, der hele tiden vil bestemme over andre?","o":["dominerende","medgørlig","tilbageholdende","pålidelig"],"a":"dominerende","r":"Den dominerende tager styringen og fylder meget. Den medgørlige gør derimod gerne, som andre foreslår."},
{"l":4955,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i sætningen skal have stort: 'Min mor taler tysk med vores gæst fra hamburg.'?","o":["tysk","hamburg","gæst","mor"],"a":"hamburg","r":"Bynavne skrives med stort. Sprog som tysk skrives med lille."},
{"l":4972,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvordan finder en laks tilbage til den å, den blev født i? Laksen kan svømme tusindvis af kilometer i havet og alligevel vende hjem for at lægge æg. Man mener, at den husker lugten af sin å. Derfor er det vigtigt, at åerne ikke bliver forurenet, for så kan fisken ikke finde hjem.' Hvad er forbindelsen mellem forurening og laksen?","o":["Forurening gør, at fisken svømmer hurtigere","Forurening gør havet farligt for laksens æg","Forurening kan ændre den lugt, laksen følger","Forurening får laksen til at holde op med at spise"],"a":"Forurening kan ændre den lugt, laksen følger","r":"Laksen følger lugten. Hvis åen forurenes, kan den ikke finde hjem. Man må sætte de to oplysninger sammen."},
{"l":4993,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at kunne': 'Vi har ikke ___ finde vej i mørket.'","o":["kunne","kan","skal","kunnet"],"a":"kunnet","r":"Efter 'har' står tillægsformen, og den hedder 'kunnet' med -t. Fejlen 'har kunne' er meget almindelig."},
{"l":5009,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem er den etbenede sørøver i Robert Louis Stevensons 'Skatteøen'?","o":["Long John Silver","Robinson Crusoe","Phileas Fogg","Tom Sawyer"],"a":"Long John Silver","r":"Long John Silver er bogens snu sørøver. Han er både charmerende og farlig, og det gør ham til en spændende modstander."},
{"l":5030,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Fabrikkens ___ holdt en tale for alle de ansatte.'","o":["derektør","direktør","direkttør","diraktør"],"a":"direktør","r":"Ordet har i og e i de to første stavelser og ender på -ør."},
{"l":5048,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at blive': 'Det er ___ koldt i aften.'","o":["blev","bliver","blevet","blive"],"a":"blevet","r":"Efter 'er' står tillægsformen 'blevet' og danner førnutid. 'Blev' er datid."},
{"l":5069,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning vil du skrive på tavlen, når ledsætningen om solen står først?","o":["Når solen, skinner går vi på stranden.","Når solen skinner går, vi på stranden.","Når solen skinner går vi, på stranden.","Når solen skinner, går vi på stranden."],"a":"Når solen skinner, går vi på stranden.","r":"Ledsætningen er 'Når solen skinner'. Kommaet skal stå lige efter den, foran hovedsætningens udsagnsled."},
{"l":5088,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn skal stå på stregen, når du skriver om tiåret fra 1990 til 1999: '1990___erne'?","o":["apostrof","komma","kolon","punktum"],"a":"apostrof","r":"Når en endelse sættes på et tal, bruger man apostrof: 1990'erne."},
{"l":5107,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Den nye rapport 'kaster lys over' problemet. Hvad gør den?","o":["den gør det større og værre","den gør det lettere at forstå","den får det til at forsvinde","den skjuler det for læserne"],"a":"den gør det lettere at forstå","r":"Ligesom lys hjælper en med at se, hjælper rapporten med at forstå, hvad der sker."},
{"l":5126,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Familien ___ skraldet i fire spande.'","o":["sortere","sorteret","sorterer","sorrterer"],"a":"sorterer","r":"Sætningen står i nutid, så navnemåden på -ere får et ekstra r."},
{"l":5146,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er ledsætningen i: 'Jeg håber, at du kommer til min fest.'","o":["grundled","hensynsled","udsagnsled","genstandsled"],"a":"genstandsled","r":"Spørg: Hvad håber jeg? Svaret er hele ledsætningen, så den fungerer som genstandsled."},
{"l":5166,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Faster Kirsten fortæller altid historien om, da hun reddede en dreng op af havet i 1975. Hvert år bliver bølgerne lidt højere, og drengen lidt mindre. Sidste jul var det næsten en orkan. Vi nikker bare og tager en småkage mere. Det er jo hendes historie.' Hvad er familiens holdning til historien?","o":["De ved, at den vokser, men lader hende fortælle i fred","De tror hvert ord, hun siger, og er meget imponerede","De er trætte af hende og vil have, at hun holder op","De mener, at hun aldrig har reddet nogen fra vandet"],"a":"De ved, at den vokser, men lader hende fortælle i fred","r":"Fortælleren lægger mærke til overdrivelserne, men accepterer dem med et smil. 'Det er jo hendes historie.'"},
{"l":5186,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hun hed Maria og boede i vores opgang. Hver gang jeg stod på trappen med min bold, ringede hun til mor. Hun var den slags voksen, der altid holder øje. Jeg hadede det. Men da jeg som tolvårig faldt af min cykel foran opgangen, var det hende, der kom ned med plaster og sagde, at hun havde set det hele.' Hvad bliver tydeligt i slutningen?","o":["At Maria har lagt en sten foran opgangen med vilje","At Maria holder øje af omsorg, ikke kun af irritation","At Maria er flyttet ind i fortællerens lejlighed","At fortælleren stadig hader alt ved hende"],"a":"At Maria holder øje af omsorg, ikke kun af irritation","r":"Det, der før var irriterende, viser sig at være en form for omsorg. Hun ser alt, også når der er brug for hjælp."},
{"l":5205,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket af ordene giver det mest negative billede af en, der tror på sig selv?","o":["selvsikker","modig","arrogant","sikker"],"a":"arrogant","r":"En arrogant person ser ned på andre. 'Selvsikker' kan derimod sagtens være positivt ment."},
{"l":5223,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om far har både hensynsled og genstandsled?","o":["Far læste en ny bog.","Far sad med en bog.","Far læste højt for mig.","Far gav mig en ny bog."],"a":"Far gav mig en ny bog.","r":"'Mig' er modtageren og altså hensynsled, og 'en ny bog' er genstandsled. De andre sætninger har højst ét af dem."},
{"l":5246,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavning: 'Vinduet er lavet af ___ glas.'","o":["gennemsigtig","gennemsigti","gennemsiktig","genemsigtig"],"a":"gennemsigtig","r":"Ordet begynder med 'gennem' med dobbelt n, og der står g foran t."},
{"l":5266,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det sidste, Hussein så af sit hjemland, var sin farmors hænder på et gelænder. Han var seks. Nu var han tolv og læste højt på dansk for klassen. Han kom til ordet hjem og gik i stå. Det var ikke, fordi det var svært at læse. Læreren ventede uden at sige noget.' Hvorfor går Hussein i stå?","o":["Ordet er et af de sværeste ord på dansk","Ordet vækker noget stort og vanskeligt i ham","Han er blevet træt af at læse højt for klassen","Han ved ikke, hvad ordet betyder på dansk"],"a":"Ordet vækker noget stort og vanskeligt i ham","r":"Teksten siger, at det ikke er ordet, der er svært at læse. Det er det, ordet betyder for ham, der stopper ham."},
{"l":5286,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I en tid, hvor alt skal gå stærkt, har en kommune i Nordjylland indført et ur, der kun går halvt så hurtigt som andre ure. Du læste rigtigt. Nej, det har den ikke. Men hvor mange kommuner ville ikke have godt af at prøve det? Mit forslag står åbent, hvis nogen gider.' Hvilken type tekst ligner dette mest?","o":["En fagtekst om tid og ure i Danmark","En nyhed om en kommune i Nordjylland","En klumme med et glimt i øjet","En brugsanvisning til et særligt ur"],"a":"En klumme med et glimt i øjet","r":"Skribenten leger med læseren, indrømmer spøgen og kommer med en personlig holdning. Det er typisk for en klumme."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver sommer målte far os mod dørkarmen med en blyant. Da huset var solgt og flyttebilen ventede, gik jeg tilbage og tog et billede af stregerne.' Hvad står blyantstregerne for?","o":["Farens evner som håndværker","De reparationer, huset mangler","Købernes planer med dørkarmen","Minderne om barndommen i huset"],"a":"Minderne om barndommen i huset","r":"Stregerne viser, hvordan børnene voksede op. Fotografiet er et forsøg på at tage minderne med, når huset forlades."},
{"l":5316,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad er punktummets opgave i tallet '2.500 kr.'?","o":["Det adskiller tusinder fra hundreder","Det viser, at tallet er et decimaltal","Det viser, at tallet er et ordenstal","Det viser, at sætningen slutter her"],"a":"Det adskiller tusinder fra hundreder","r":"Punktummet gør store tal lettere at læse. Decimaler skrives med komma på dansk."},
{"l":5333,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om svømmehallen har den rigtige ordstilling?","o":["I morgen vi skal i svømmehallen.","I morgen skal vi i svømmehallen.","I morgen vi i svømmehallen skal.","I morgen skal i svømmehallen vi."],"a":"I morgen skal vi i svømmehallen.","r":"Når noget andet end grundleddet står først i en hovedsætning, kommer udsagnsleddet på andenpladsen og grundleddet lige efter."},
{"l":5354,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Han hedder Max. Hvilken form passer: 'I dag er det ___ fødselsdag.'?","o":["Max's","Maxs","Max'","Ma'x"],"a":"Max'","r":"Navne på s, x og z får kun apostrof i ejefald."},
{"l":5373,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvor mangler kommaet: 'Selvom hun var træt læste Leila to kapitler.'?","o":["efter hun","efter læste","efter to","efter træt"],"a":"efter træt","r":"'Selvom hun var træt' er en ledsætning. Kommaet viser, hvor den slutter og hovedsætningen begynder."},
{"l":5392,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad bruges anførselstegnene til i: 'Ordet »hygge« kendes over hele verden.'?","o":["At vise, at man omtaler selve ordet","At vise, at ordet er stavet forkert","At vise, at ordet er en forkortelse","At vise, at sætningen er et spørgsmål"],"a":"At vise, at man omtaler selve ordet","r":"Man kan sætte anførselstegn om et ord, når man taler om ordet og ikke om det, ordet betyder."},
{"l":5410,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken slags stedord er 'vores' i: 'Vores lærer har en hund.'","o":["påpegende stedord","ejestedord","ubestemt stedord","spørgende stedord"],"a":"ejestedord","r":"'Vores' fortæller, hvem læreren hører til. Det kaldes også et possessivt pronomen."},
{"l":5431,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'ubestrideligt'?","o":["at man ikke kan komme igennem det uden hjælp","at man ikke må tale om det i offentligheden","at man ikke kan sætte spørgsmålstegn ved det","at man ikke længere kan købe det i butikkerne"],"a":"at man ikke kan sætte spørgsmålstegn ved det","r":"At bestride noget er at sige imod. Noget ubestrideligt kan ingen med rimelighed sige imod."},
{"l":5450,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Der lød en høj ___, da vulkanen gik i udbrud.'","o":["eksplotion","explosion","eksplosjon","eksplosion"],"a":"eksplosion","r":"Ordet begynder med eks og ender på -sion, ikke på -tion."},
{"l":5468,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer? 'Hans undskyldning virkede ___, for han smilede hånligt, mens han sagde den.'","o":["uoprigtig","ydmyg","hjertelig","ægte"],"a":"uoprigtig","r":"Den, der er uoprigtig, mener ikke det, vedkommende siger. Det hånlige smil afslører undskyldningen."},
{"l":5487,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'før' i: 'Før middagen vasker vi hænder.'","o":["bindeord","forholdsord","biord","stedord"],"a":"forholdsord","r":"'Før' står foran navneordet 'middagen' og styrer det. Så er det et forholdsord."},
{"l":5507,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad gør prinsen til sidst i H.C. Andersens 'Svinedrengen'?","o":["Han gifter sig med prinsessen på sit eget slot","Han giver prinsessen den rose, hun før ville have","Han forlader prinsessen, fordi hun ikke så det ægte","Han sender prinsessen i fængsel på kongens slot"],"a":"Han forlader prinsessen, fordi hun ikke så det ægte","r":"Prinsessen afviste den ægte rose og nattergal, men kyssede svinedrengen for legetøj. Derfor vender han hende ryggen."},
{"l":5528,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'krydse klinger' med nogen?","o":["at blive gode venner med nogen","at arbejde stille sammen med nogen","at undgå at møde nogen","at diskutere hidsigt med nogen"],"a":"at diskutere hidsigt med nogen","r":"Klinger er sværd, men i dag bruges udtrykket om en skarp ordveksling, ikke en rigtig kamp."},
{"l":5546,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Sangeren synger i en ___ på scenen.'","o":["mikrofon","mikrophon","mikrafon","mickrofon"],"a":"mikrofon","r":"På dansk skrives f-lyden f, og ordet har o efter r."},
{"l":5566,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord mangler? 'Et ___ råd er et råd, man giver uden at være blevet spurgt.'","o":["ubrugeligt","uopfordret","uvurderligt","uundgåeligt"],"a":"uopfordret","r":"At opfordre er at bede nogen om noget. Noget uopfordret gør man, uden at nogen har bedt om det."},
{"l":5586,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Hver af pigerne fik ___ egen lineal.'","o":["sit","sine","sin","hans"],"a":"sin","r":"'Hver' er ental, og 'lineal' er fælleskøn. Derfor hedder det 'sin egen lineal'."},
{"l":5603,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem indsamlede mange jyske folkeeventyr og sagn i 1800-tallet?","o":["Ludvig Holberg","Søren Kierkegaard","Knud Rasmussen","Evald Tang Kristensen"],"a":"Evald Tang Kristensen","r":"Evald Tang Kristensen var lærer og rejste rundt i Jylland for at skrive folkets fortællinger ned. Han reddede dermed mange historier."},
{"l":5626,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren beder om flere 'nuancer' i analysen. Hvad er en nuance?","o":["en lille forskel i farve eller betydning","en fejl i en tekst eller et regnestykke","en meget stor og tydelig modsætning","et citat fra en kendt forfatter"],"a":"en lille forskel i farve eller betydning","r":"Nuancer er de små forskelle. En nuanceret analyse viser, at en sag ikke kun er sort eller hvid."},
{"l":5642,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi har lært, at Grønlands indlandsis smelter, og det er sandt. Men det, der smelter hurtigt, er ikke kun isen. Det er også sprog. Mange steder i verden uddør små sprog, når den sidste gamle taler dør. Sammen med sproget forsvinder ord for ting, som ingen andre sprog har ord for.' Hvad er sammenligningen i teksten?","o":["At grønlandsk er det sprog i verden, der har flest ord for is","At isen og sprog begge er noget, der kan forsvinde for altid","At sprog bliver talt mest på steder, hvor der er meget is","At gamle mennesker bedst kan fortælle om smeltende is"],"a":"At isen og sprog begge er noget, der kan forsvinde for altid","r":"Teksten bruger smeltende is som billede på sprog, der forsvinder. Tabet er det, de har til fælles."},
{"l":5663,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at lade': 'I fredags ___ læreren os gå tidligere.'","o":["ladet","lader","lod","lade"],"a":"lod","r":"'At lade' bøjes lader, lod, har ladet. 'I fredags' kræver datid."},
{"l":5685,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at træffe': 'Hun har ___ en vigtig beslutning.'","o":["traf","træffer","træffe","truffet"],"a":"truffet","r":"'At træffe' bøjes træffer, traf, har truffet. Efter 'har' står tillægsformen."},
{"l":5707,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at sværge': 'Dengang ___ ridderne kongen troskab.'","o":["svor","svoret","sværger","sværge"],"a":"svor","r":"'At sværge' er meget uregelmæssigt: sværger, svor, har svoret. 'Dengang' viser, at der skal stå datid."},
{"l":5727,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er verballed (udsagnsled) i sætningen: 'Min storebror cykler altid til skole.'?","o":["altid","cykler","storebror","skole"],"a":"cykler","r":"Verballeddet fortæller, hvad der sker. 'Altid' er et biord, der siger noget om, hvor tit det sker."},
{"l":5746,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Vi gik ___ den smalle sti gennem skoven.'","o":["af","at","ad","og"],"a":"ad","r":"'Ad' bruges om den vej, man bevæger sig hen ad. 'Af' fortæller ikke om ruten."},
{"l":5767,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Månen var en sølvmønt på himlen.' Hvilket sprogligt billede er der her?","o":["sammenligning","gentagelse","allitteration","metafor"],"a":"metafor","r":"Månen kaldes direkte en sølvmønt, uden 'som' eller 'ligesom'. Derfor er det en metafor og ikke en sammenligning."},
{"l":5785,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ordenstal passer? 'December er årets ___ måned.'","o":["tolvte","tolvde","tollvte","tolfte"],"a":"tolvte","r":"Ordet er dannet af 'tolv' med endelsen -te. V'et bliver stående."},
{"l":5804,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord i sætningen er et ejestedord: 'Mikkel lånte min oplader i går.'?","o":["Mikkel","min","lånte","oplader"],"a":"min","r":"Et ejestedord fortæller, hvem noget tilhører. 'Min' viser, at opladeren tilhører den, der taler."},
{"l":5824,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Kan du ___ mig, hvordan man løser ligningen?'","o":["vide","visse","vise","vidse"],"a":"vise","r":"'Vise' betyder at lade nogen se noget. 'Vide' betyder at have kendskab til noget."},
{"l":5843,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad beskæftiger en 'meteorolog' sig med?","o":["sten fra rummet","stjernebilleder","jordlag og mineraler","vejr og klima"],"a":"vejr og klima","r":"Ordet ligner 'meteor', men en meteorolog studerer atmosfæren og laver vejrudsigter."},
{"l":5863,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Hvor er du ___? Jeg kan ikke finde dig.'","o":["henne","hen","hene","hende"],"a":"henne","r":"Spørgsmålet gælder et sted, man er på, og så hedder det 'henne'. 'Hen' bruges om en bevægelse."},
{"l":5881,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Musik er et 'obligatorisk' fag på skolen. Hvad betyder det?","o":["at man selv kan vælge det fra","at alle er nødt til at have det","at det kun er for de ældste elever","at det ligger uden for skoletiden"],"a":"at alle er nødt til at have det","r":"Obligatorisk betyder påbudt. Det modsatte er valgfrit eller frivilligt."},
{"l":5902,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken stavemåde passer? 'Har du et godt ___ til klassens tur?'","o":["foreslag","forslå","forslag","foreslå"],"a":"forslag","r":"Navneordet skrives uden e i midten. Det er udsagnsordet at foreslå, der har e'et."},
{"l":5920,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning har kommaet på et rigtigt sted, når ledsætningen begynder med 'hvad'?","o":["Jeg forstod, ikke hvad hun mente med det.","Jeg forstod ikke hvad, hun mente med det.","Jeg forstod ikke hvad hun, mente med det.","Jeg forstod ikke, hvad hun mente med det."],"a":"Jeg forstod ikke, hvad hun mente med det.","r":"Et komma må kun stå ved sætningsgrænsen, lige før 'hvad'. Det må ikke splitte ledsætningen."},
{"l":5941,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige navneord: 'Mål bordets ___ med et målebånd.'","o":["længde","længte","lengde","længe"],"a":"længde","r":"Navneordet kommer af 'lang' og har d. 'Længe' fortæller om tid, og 'længte' kommer af 'længes'."},
{"l":5963,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad laver en 'faktatjekker' på en nyhedsredaktion?","o":["skriver overskrifter til nyhederne","undersøger, om påstande passer","sletter de kritiske læserbreve","lægger billeder ind i artiklerne"],"a":"undersøger, om påstande passer","r":"En faktatjekker kontrollerer oplysninger, for eksempel ved at sammenligne med tal og andre kilder."},
{"l":5980,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Biblioteket i Åbjerg holder nu kun åbent tre dage om ugen. Ifølge kommunen er det nødvendigt for at spare. Besøgstallet er ifølge bibliotekaren steget, siden skolen begyndte at bruge det.' Hvad gør journalisten i teksten?","o":["Går ind for, at biblioteket skal lukke helt","Forsvarer kommunens beslutning over for læseren","Gengiver to parters syn uden selv at vælge side","Kritiserer bibliotekaren for at bruge forkerte tal"],"a":"Gengiver to parters syn uden selv at vælge side","r":"Udtrykkene 'ifølge kommunen' og 'ifølge bibliotekaren' viser, at journalisten refererer andres udsagn uden at tage stilling."},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mange store opfindere klarede sig dårligt i skolen. Derfor behøver du ikke lave dine lektier.' Hvad er fejlen i slutningen?","o":["Der findes ingen kendte opfindere i dag","Lektier blev først indført efter opfinderne","Opfindere har aldrig gået i skole i Danmark","Dårlige skolepræstationer gør ingen til opfinder"],"a":"Dårlige skolepræstationer gør ingen til opfinder","r":"Selv hvis nogle opfindere var dårlige i skolen, følger det ikke, at det er vejen til succes. Eksemplerne beviser ikke råd til dig."},
{"l":6016,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket dansk navn svarer til det latinske 'direkte objekt'?","o":["genstandsled","hensynsled","grundled","omsagnsled"],"a":"genstandsled","r":"Det direkte objekt er genstandsleddet, som verbets handling går ud over. Det indirekte objekt er hensynsleddet."},
{"l":6038,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Aftalen ophører den 1. maj.' Hvad sker der den 1. maj?","o":["aftalen begynder","aftalen slutter","aftalen bliver forlænget","aftalen bliver underskrevet"],"a":"aftalen slutter","r":"'Ophøre' betyder at holde op. Ordet bruges især i kontrakter og andre formelle tekster."},
{"l":6057,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vinteren det år var den slags, hvor man lærte at gå uden at løfte fødderne. Vi talte kun, når vi måtte, for ordene frøs fast på vejen ud. Selv hunden holdt op med at gø ad posten.' Hvad vil forfatteren især skabe?","o":["En fornemmelse af spænding og fare i sneen","Et muntert billede af sjov i sneen","En fornemmelse af kulde og stilstand","En saglig beskrivelse af vejret"],"a":"En fornemmelse af kulde og stilstand","r":"Overdrivelserne viser en verden, der næsten går i stå: fødderne, ordene og hunden. Det er stemning, ikke fakta."},
{"l":6076,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Beslutningen blev truffet på en ___ måde.'","o":["demokrat","demokrati","demokratier","demokratisk"],"a":"demokratisk","r":"Foran navneordet 'måde' skal der stå et tillægsord. Endelsen -isk gør navneordet 'demokrati' til et tillægsord."},
{"l":6097,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Eleven, der ___ tysk, skal hen til lokale 12.'","o":["vælger","vælge","vælgger","vælgerer"],"a":"vælger","r":"Inde i ledsætningen står ordet i nutid: Eleven vælger. Navneformen 'vælge' kan ikke stå her."},
{"l":6110,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken form er rigtig? 'Hvis læreren ___ det én gang til, kan jeg nok løse opgaven.'","o":["forklare","forklarer","forklarrer","forklarerer"],"a":"forklarer","r":"Ordet står i nutid med 'læreren' som grundled, så navneformen 'forklare' får -r."},
{"l":6128,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad beskytter 'ophavsretten'?","o":["retten til at sige sin mening offentligt","retten til at låne bøger på biblioteket","retten til at bestemme over det, man har skabt","retten til at se film uden at betale for dem"],"a":"retten til at bestemme over det, man har skabt","r":"Ophavsretten giver forfattere, musikere og andre skabere ret til at bestemme, hvordan deres værk må bruges og kopieres."},
{"l":6149,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Luk ___, og tæl langsomt til ti.'","o":["øjenene","øjnende","øjnerne","øjnene"],"a":"øjnene","r":"Flertal af 'øje' er 'øjne', og den bestemte form får -ne: øjnene. Der er intet d, for det er ikke en -ende-form."},
{"l":6173,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I et brev fra kommunen står der: 'Vi beklager ulejligheden.' Hvad betyder det?","o":["vi er kede af det besvær, du har haft","vi klager over det besvær, du har givet os","vi er glade for, at du har kontaktet os","vi kan ikke svare før efter ferien"],"a":"vi er kede af det besvær, du har haft","r":"At beklage er at undskylde eller udtrykke, at man er ked af noget. Det er noget andet end at klage over nogen."},
{"l":6192,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken relativsætning har rigtig ordstilling: 'Det er en film, …'?","o":["som jeg har aldrig set","som jeg aldrig har set","som aldrig jeg har set","som har jeg aldrig set"],"a":"som jeg aldrig har set","r":"I en ledsætning står biord som 'aldrig' foran det bøjede verbum: 'jeg aldrig har set'."},
{"l":6203,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et firma har 'monopol' på et produkt. Hvad betyder det?","o":["det sælger produktet billigere end alle andre","det har opfundet produktet for nylig","det er det eneste firma, der sælger produktet","det sælger produktet i alle lande i verden"],"a":"det er det eneste firma, der sælger produktet","r":"'Mono' betyder én. Uden konkurrenter kan et firma med monopol selv sætte prisen meget frit."},
{"l":6225,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Du skriver et officielt brev. Hvilket ord for 'at få' er mest formelt?","o":["snuppe","hapse","nappe","modtage"],"a":"modtage","r":"'Modtage' hører til det formelle skriftsprog. De andre ord er uformelle og passer bedre til samtale."},
{"l":6243,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hele klassen grinede. Mira sagde ingenting. Hun tog sin taske og gik ud i regnen.' Hvilken synsvinkel har teksten?","o":["Ydre synsvinkel","Indre synsvinkel","Alvidende synsvinkel","Du-synsvinkel"],"a":"Ydre synsvinkel","r":"Vi ser kun, hvad personerne gør og siger, ikke hvad de tænker. Det er en ydre synsvinkel."},
{"l":6263,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et land har en valgt præsident som statsoverhoved i stedet for en konge eller dronning. Hvad kaldes sådan en styreform?","o":["monarki","republik","diktatur","koloni"],"a":"republik","r":"I en republik vælges statsoverhovedet for en periode. I et monarki går posten i arv, sådan som i Danmark."},
{"l":6290,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find omsagnsleddet (prædikativet): 'Lukas er blevet en dygtig lærer.'","o":["Lukas","er blevet","en dygtig lærer","er"],"a":"en dygtig lærer","r":"Omsagnsleddet siger noget om grundleddet efter verber som 'være' og 'blive'. Lukas og læreren er den samme person, så det er ikke et genstandsled."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolens søjlediagram sammenligner to klassers læsescorer: 102 og 104. Diagrammets lodrette akse begynder ved 100, så den ene søjle ser dobbelt så høj ud som den anden.' Hvilken virkning har valget af akse?","o":["Forskellen forsvinder for den, der læser diagrammet","Tallene for klasserne bliver ændret i diagrammet","Læseren kan slet ikke se, hvilken klasse der scorer højest","Forskellen virker langt større, end den faktisk er"],"a":"Forskellen virker langt større, end den faktisk er","r":"Forskellen er kun to point, men den afskårne akse puster den op. Tallene er rigtige, men billedet vildleder."},
{"l":6318,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer? 'Efter prøven var Ida godt ___ med sit resultat.'","o":["tilfreds","tilfres","tillfreds","tilfredds"],"a":"tilfreds","r":"Ordet indeholder 'fred', så der skal et stumt d med. 'Til-' har kun ét l."},
{"l":6340,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn binder to tætte hovedsætninger sammen i: 'Butikken var lukket ___ vi måtte gå tomhændede hjem.'?","o":["apostrof","semikolon","bindestreg","anførselstegn"],"a":"semikolon","r":"Semikolon kan stå mellem to hovedsætninger, der hører tæt sammen."},
{"l":6360,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når ledsætningen indeholder to handlinger, 'spist' og 'ryddet op'?","o":["Da vi havde spist, og ryddet op gik vi en tur.","Da vi havde spist og ryddet op gik vi, en tur.","Da vi havde spist og ryddet op, gik vi en tur.","Da vi, havde spist og ryddet op gik vi en tur."],"a":"Da vi havde spist og ryddet op, gik vi en tur.","r":"De to handlinger hører til samme ledsætning. Den slutter efter 'ryddet op', og der skal kommaet stå."},
{"l":6380,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Mit yndlingseventyr er kejserens nye klæder.'?","o":["yndlingseventyr","nye","klæder","kejserens"],"a":"kejserens","r":"Titlen på eventyret er 'Kejserens nye klæder'. Kun det første ord i titlen får stort."},
{"l":6400,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket bindeord gør ledsætningen til en tidsangivelse: 'Telefonen ringede, ___ vi spiste.'?","o":["mens","fordi","hvis","selvom"],"a":"mens","r":"'Mens' fortæller, at to ting sker samtidig. 'Fordi' angiver årsag, 'hvis' betingelse og 'selvom' indrømmelse."},
{"l":6420,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tilhængere af at sænke valgretsalderen til 16 år siger, at unge også bliver berørt af beslutningerne. Modstandere siger, at man bør være myndig, før man kan stemme. Begge sider henviser til, hvad der er retfærdigt.' Hvordan forholder teksten sig til emnet?","o":["Den går ind for at sænke valgretsalderen til 16 år","Den fremlægger to synspunkter uden at tage stilling","Den forsvarer, at man skal være myndig for at stemme","Den afviser, at emnet handler om retfærdighed"],"a":"Den fremlægger to synspunkter uden at tage stilling","r":"Teksten refererer begge sider med ordene 'siger' og fælder ingen dom. Det er neutral, redegørende sagprosa."},
{"l":6440,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken af sætningerne skal slutte med punktum og ikke spørgsmålstegn?","o":["Hvem af jer har glemt sin taske her i klassen i dag","Har du glemt din taske i bussen på vej hjem fra skole","Læreren ville vide, hvem der havde glemt sin taske","Hvorfor tager du ikke din taske med hjem efter timen"],"a":"Læreren ville vide, hvem der havde glemt sin taske","r":"Det er indirekte tale: Sætningen fortæller, hvad læreren ville vide, men stiller ikke selv spørgsmålet."},
{"l":6461,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Af hensyn til din ___ skal du bruge cykelhjelm.'","o":["sikerhed","sikkerhet","sikkerhedd","sikkerhed"],"a":"sikkerhed","r":"Ordet kommer af 'sikker' og har derfor dobbelt-k. Endelsen hedder -hed."},
{"l":6481,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I en novelle vokser en lille plante op gennem asfalten, lige efter at en dreng har mistet modet. Hvad er planten bedst symbol på?","o":["håb","vrede","rigdom","kedsomhed"],"a":"håb","r":"Noget levende, der kæmper sig frem på et hårdt sted, peger på, at der stadig er liv og håb. Placeringen lige efter drengens nederlag understreger det."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer? 'Ekspedienten hjalp en ___ med at finde en jakke.'","o":["kunne","kunde","kune","kundde"],"a":"kunde","r":"En kunde er en, der køber noget. 'Kunne' er et udsagnsord, som ikke giver mening efter 'en'."},
{"l":6513,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er den rigtige stavemåde? 'Bilen står i vores ___ om natten.'","o":["garrage","garasje","garage","gerage"],"a":"garage","r":"Ordet kommer fra fransk. Det har kun ét r og ender på -age, selvom det lyder som -asje."},
{"l":6532,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Solen går ned bag det gamle træ, / lammene sover i ly og læ.' Hvilken slags rim er der mellem 'træ' og 'læ'?","o":["bogstavrim","indrim","metafor","enderim"],"a":"enderim","r":"Ordene rimer, og de står sidst i hver sin linje. Derfor er det enderim."},
{"l":6552,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lindeskolen har 420 elever. Skolen ligger 200 meter fra skoven. Det er den hyggeligste skole i kommunen. Der er to klasser på hver årgang.' Hvilken sætning er en vurdering og ikke en oplysning?","o":["Det er den hyggeligste skole i kommunen.","Skolen ligger 200 meter fra skoven.","Lindeskolen har 420 elever.","Der er to klasser på hver årgang."],"a":"Det er den hyggeligste skole i kommunen.","r":"Hygge er en mening, som andre kan være uenige i. De andre sætninger kan kontrolleres med tal og målinger."},
{"l":6574,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg bor på en gade, hvor alle hilser, og ingen ved noget.' Hvad siger jeg-personen om sine naboer?","o":["De er sure, men ved alt om alle på gaden","De er venlige, men kender ikke hinanden rigtigt","De hilser kun på dem, de kender godt i forvejen","De taler kun om det, de ikke ved noget om"],"a":"De er venlige, men kender ikke hinanden rigtigt","r":"Sætningen bygger på en modsætning: Hilsner viser høflighed, men 'ingen ved noget' viser, at det stopper der."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
